# NEXA NIA Memory Phase 8 Test Script

Set-Location $PSScriptRoot

python -c "from memory_service import MemoryService; service = MemoryService(); service.remember_semantic('NEXA is a persistent simulated world that continues independently of individual audience commands.', tags=['nexa', 'persistent', 'world']); service.remember_episodic(content='EVENT 2044: NIA watched Brian expose corruption in the City Government procurement office.', event_id='EVENT_2044', subject_ids=['brian', 'city_government'], importance=91, emotional_weight=87, relationship=82, secrecy=54, tags=['event_2044', 'brian', 'corruption', 'government']); service.remember_secret(content='Brian privately told NIA that a second official may be involved in the procurement corruption case.', subject_ids=['brian'], secrecy=90, importance=85, tags=['brian', 'corruption', 'secret']); service.relationships.remember_character(character_id='brian', character_name='Brian', impression='NIA respects Brian for exposing corruption but is concerned for his safety.', trust=78, affection=55, fear=35, respect=91, resentment=5); service.add_conversation_message('USER', 'What does NIA remember about Brian?'); service.add_conversation_message('NIA', 'I remember an important public event involving Brian and corruption.'); restarted_service = MemoryService(); nia_memories = restarted_service.retrieve_for_nia('What happened when Brian exposed corruption?', limit=5); audience_memories = restarted_service.retrieve_for_user('What happened when Brian exposed corruption?', player_id='audience', clearance=0, limit=5); print('NEXA Phase 8 Memory Test Complete'); print(); print('Persistent memory records:', len(restarted_service.store.all())); print('Short-term messages retained only in the active service:', len(service.get_short_term_context())); print(); print('NIA authorised retrieval:'); [print(f'  Score {item['retrieval_score']}: {item['memory']['content']}') for item in nia_memories]; print(); print('Audience authorised retrieval:'); [print(f'  Score {item['retrieval_score']}: {item['memory']['content']}') for item in audience_memories]; print(); print('PASS: NIA can retrieve private authorised memory; ordinary audience retrieval excludes secret memory.')"
